<script setup lang="ts">import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import {money} from '../data/demo';import {useLoanStore} from '../stores/loan';import PageNav from '../components/PageNav.vue';import PrototypeNotice from '../components/PrototypeNotice.vue';const store=useLoanStore(),router=useRouter();const amount=ref(store.loanDraft.amount),term=ref(store.loanDraft.term),purpose=ref(store.loanDraft.purpose);const monthly=computed(()=>amount.value/term.value+amount.value*0.108/12);const next=()=>{store.loanDraft={...store.loanDraft,amount:amount.value,term:term.value,purpose:purpose.value};router.push('/contract')}</script>
<template><main class="page loan-form"><PageNav title="申请借款"/><section class="amount-picker"><span>借款金额（元）</span><div><small>¥</small><input v-model.number="amount" type="number"/></div><p>可借额度 {{money(store.availableLimit)}}</p><van-slider v-model="amount" :min="1000" :max="store.availableLimit" :step="500" bar-height="5px"/></section><van-cell-group inset><van-cell title="借款期数"><template #value><van-radio-group v-model="term" direction="horizontal"><van-radio :name="3">3期</van-radio><van-radio :name="6">6期</van-radio><van-radio :name="12">12期</van-radio></van-radio-group></template></van-cell><van-field v-model="purpose" label="借款用途" readonly is-link/><van-field :model-value="store.loanDraft.bank" label="收款账户" readonly is-link/></van-cell-group><section class="cost-card"><div><span>预计每期应还</span><strong>{{money(monthly)}}</strong></div><p>包含本金及利息，实际金额以审批结果和合同为准</p><van-cell title="参考年化利率" value="10.8%"/><van-cell title="总利息（估算）" :value="money(monthly*term-amount)"/></section><PrototypeNotice/><BottomActionBar><van-button round block type="primary" @click="next">确认借款信息</van-button></BottomActionBar></main></template>
